                add_back = dist_of(route[-1], c) + dist_of(c, depot) - dist_of(route[-1], depot)
                inc = add_front if add_front < add_back else add_back
                key = (inc, -dc, c)
                if best is None or key < best_key:
                    best = (c, "front" if add_front < add_back else "back")
                    best_key = key
            if best is None:
                break
            c, side = best
            if side == "front":
                route.insert(0, c)
            else:
                route.append(c)
            unassigned.remove(c)
            load += demand_of(c)

        routes.append(route)

    # Repair: split any over-capacity route if needed
    repaired = []
    for r in routes:
        cur = []
        load = 0
        for c in r:
            dc = demand_of(c)
            if load + dc > capacity and cur:
                repaired.append(cur)
                cur = [c]
                load = dc
            else:
                cur.append(c)
                load += dc
        if cur:
            repaired.append(cur)
    routes = repaired

    # Improvement: relocate customers between routes
    improved = True
    iterations = 0
    while improved and iterations < 60:
        iterations += 1
        improved = False
        best_move = None
        best_gain = 0

        for i in range(len(routes)):
            ri = routes[i]
            li = route_load(ri)
            for pos in range(len(ri)):
                c = ri[pos]
                dc = demand_of(c)
                ri_prev = depot if pos == 0 else ri[pos - 1]
                ri_next = depot if pos == len(ri) - 1 else ri[pos + 1]
                remove_saving = dist_of(ri_prev, c) + dist_of(c, ri_next) - dist_of(ri_prev, ri_next)

                # move to another route
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    lj = route_load(rj)
                    if lj + dc > capacity:
                        continue
                    # best insertion position in rj
                    best_pos_gain = None
                    best_pos = None
                    for ins in range(len(rj) + 1):
                        a = depot if ins == 0 else rj[ins - 1]
                        b = depot if ins == len(rj) else rj[ins]
                        add_cost = dist_of(a, c) + dist_of(c, b) - dist_of(a, b)
                        if best_pos_gain is None or add_cost < best_pos_gain:
                            best_pos_gain = add_cost
                            best_pos = ins
                    gain = remove_saving - best_pos_gain
                    if gain > 1e-12 and (gain > best_gain or (gain == best_gain and (i, j, pos, best_pos, c) < best_move[0] if best_move else True)):
                        best_gain = gain
                        best_move = ((i, j, pos, best_pos, c), gain)

        if best_move is not None:
            (i, j, pos, ins, c), gain = best_move
            if i < j:
                rj = routes[j]
                ri = routes[i]
            else:
                ri = routes[i]
                rj = routes[j]
            # re-fetch because list order unchanged
            routes[i].pop(pos)
            if i == j:
                continue
            if ins > len(routes[j]):
                ins = len(routes[j])
            routes[j].insert(ins, c)
            if not routes[i]:
                routes.pop(i)
            improved = True

    # Try simple route merging if possible
    merged = True
    while merged:
        merged = False
        best_pair = None
        best_saving = 0
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                if route_load(ri) + route_load(rj) > capacity:
                    continue
                candidates = [
                    (ri + rj,
                     dist_of(depot, ri[0]) + dist_of(ri[-1], depot) + dist_of(depot, rj[0]) + dist_of(rj[-1], depot)
                     - (dist_of(depot, (ri + rj)[0]) + dist_of((ri + rj)[-1], depot))),
                    (ri + list(reversed(rj)),
                     dist_of(depot, ri[0]) + dist_of(ri[-1], depot) + dist_of(depot, rj[-1]) + dist_of(rj[0], depot)
                     - (dist_of(depot, (ri + list(reversed(rj)))[0]) + dist_of((ri + list(reversed(rj)))[-1], depot))),
                    (list(reversed(ri)) + rj,
                     dist_of(depot, ri[-1]) + dist_of(ri[0], depot) + dist_of(depot, rj[0]) + dist_of(rj[-1], depot)
                     - (dist_of(depot, (list(reversed(ri)) + rj)[0]) + dist_of((list(reversed(ri)) + rj)[-1], depot))),
                    (list(reversed(ri)) + list(reversed(rj)),
                     dist_of(depot, ri[-1]) + dist_of(ri[0], depot) + dist_of(depot, rj[-1]) + dist_of(rj[0], depot)
                     - (dist_of(depot, (list(reversed(ri)) + list(reversed(rj)))[0]) + dist_of((list(reversed(ri)) + list(reversed(rj)))[-1], depot))),
                ]
                for cand, saving in candidates:
                    if saving > best_saving:
                        best_saving = saving
                        best_pair = (i, j, cand)
        if best_pair is not None:
            i, j, cand = best_pair
            routes[i] = cand
            routes.pop(j)
            merged = True

    # Final cleanup: remove empty routes, ensure every customer exactly once by reconstruction if needed
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    if len(seen) != len(customers) or any(v != 1 for v in seen.values()):
        # deterministic fallback reconstruction
        routes = []
        remaining = sorted(customers, key=lambda c: (demand_of(c), c))
        while remaining:
            r = []
            load = 0
            last = depot
            i = 0
            while i < len(remaining):
                c = remaining[i]
                dc = demand_of(c)
                if load + dc <= capacity:
                    # append nearest feasible from current last
                    best_idx = None
                    best_val = None
                    for idx in range(len(remaining)):
                        x = remaining[idx]
                        dx = demand_of(x)
                        if load + dx <= capacity:
                            val = dist_of(last, x)
                            key = (val, dx, x)
                            if best_val is None or key < best_val:
                                best_val = key
                                best_idx = idx
                    if best_idx is None:
                        break
                    c = remaining.pop(best_idx)
                    r.append(c)
                    load += demand_of(c)
                    last = c
                    i = 0
                else:
                    i += 1
            if not r and remaining:
                c = remaining.pop(0)
                r.append(c)
            routes.append(r)

    return [r for r in routes if r]
